1	/**
2	 * pr-label-assigner — core logic.
3	 *
4	 * Given a list of changed file paths (a PR's diff) and a set of
5	 * path-to-label mapping rules, compute the final set of labels.
6	 *
7	 * Features:
8	 *   - Glob patterns (via Bun.Glob): `docs/**`, `src/api/**`, `*.test.*`
9	 *   - Multiple labels per file (a file may match many rules)
10	 *   - Multiple files contribute to one shared label set
11	 *   - Priority ordering so the output is deterministic when rules "conflict"
12	 *     (i.e. when several rules contribute different labels): higher priority
13	 *     labels are emitted first.
14	 */
15	
16	/** A single path-to-label mapping rule. */
17	export interface Rule {
18	  /** Glob pattern matched against changed file paths. */
19	  pattern: string;
20	  /** Label applied to the PR when at least one file matches `pattern`. */
21	  label: string;
22	  /**
23	   * Higher numbers rank earlier in the output. Defaults to 0.
24	   * Used to break ties / impose a stable conflict ordering.
25	   */
26	  priority?: number;
27	}
28	
29	/**
30	 * Determine whether a single file path matches a single glob pattern.
31	 *
32	 * Uses Bun's built-in `Bun.Glob` for standard glob semantics:
33	 *   - `*`  matches any run of characters except `/`
34	 *   - `**` matches across directory separators
35	 *
36	 * Convenience: when a pattern contains no `/` (e.g. `*.test.*`), we also try
37	 * matching it against the file's basename. This lets short patterns target
38	 * files at any depth, matching the intuitive expectation in the task spec
39	 * (`*.test.*` -> tests, regardless of which folder the test lives in).
40	 */
41	export function matchesPattern(filePath: string, pattern: string): boolean {
42	  const glob = new Bun.Glob(pattern);
43	  if (glob.match(filePath)) return true;
44	
45	  if (!pattern.includes("/")) {
46	    const basename = filePath.split("/").pop() ?? filePath;
47	    return glob.match(basename);
48	  }
49	  return false;
50	}
51	
52	/**
53	 * Compute the final, ordered, de-duplicated set of labels for a PR.
54	 *
55	 * Ordering rules (deterministic):
56	 *   1. By the highest priority among the rules that produced the label (desc).
57	 *   2. Ties broken by label name (ascending) for stable, predictable output.
58	 *
59	 * @param files Changed file paths (the mocked PR file list).
60	 * @param rules Path-to-label mapping rules.
61	 * @returns Unique labels, ordered by priority then name.
62	 */
63	export function assignLabels(files: string[], rules: Rule[]): string[] {
64	  if (!Array.isArray(files)) {
65	    throw new TypeError("assignLabels: `files` must be an array of strings");
66	  }
67	  if (!Array.isArray(rules)) {
68	    throw new TypeError("assignLabels: `rules` must be an array of rules");
69	  }
70	
71	  // Track, for each matched label, the strongest priority that produced it so
72	  // that conflicting rules order predictably.
73	  const labelPriority = new Map<string, number>();
74	
75	  for (const rule of rules) {
76	    if (typeof rule?.pattern !== "string" || typeof rule?.label !== "string") {
77	      throw new TypeError(
78	        `assignLabels: each rule needs string \`pattern\` and \`label\` (got ${JSON.stringify(
79	          rule,
80	        )})`,
81	      );
82	    }
83	    const priority = rule.priority ?? 0;
84	    const matched = files.some((file) => matchesPattern(file, rule.pattern));
85	    if (!matched) continue;
86	
87	    const existing = labelPriority.get(rule.label);
88	    if (existing === undefined || priority > existing) {
89	      labelPriority.set(rule.label, priority);
90	    }
91	  }
92	
93	  return [...labelPriority.entries()]
94	    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
95	    .map(([label]) => label);
96	}
97	
98	/**
99	 * Parse a JSON configuration document into a validated list of rules.
100	 *
101	 * Expected shape:
102	 *   { "rules": [ { "pattern": "docs/**", "label": "documentation", "priority": 1 }, ... ] }
103	 *
104	 * Throws clear, actionable errors for malformed input so CI failures are easy
105	 * to diagnose.
106	 */
107	export function parseConfig(jsonText: string): Rule[] {
108	  let parsed: unknown;
109	  try {
110	    parsed = JSON.parse(jsonText);
111	  } catch (err) {
112	    const reason = err instanceof Error ? err.message : String(err);
113	    throw new SyntaxError(`parseConfig: invalid JSON config — ${reason}`);
114	  }
115	
116	  if (typeof parsed !== "object" || parsed === null) {
117	    throw new TypeError("parseConfig: config root must be a JSON object");
118	  }
119	
120	  const rules = (parsed as { rules?: unknown }).rules;
121	  if (!Array.isArray(rules)) {
122	    throw new TypeError(
123	      "parseConfig: config must contain a `rules` array (e.g. { \"rules\": [...] })",
124	    );
125	  }
126	
127	  return rules.map((rule, i) => {
128	    if (typeof rule !== "object" || rule === null) {
129	      throw new TypeError(`parseConfig: rule at index ${i} must be an object`);
130	    }
131	    const { pattern, label, priority } = rule as Record<string, unknown>;
132	    if (typeof pattern !== "string") {
133	      throw new TypeError(
134	        `parseConfig: rule at index ${i} is missing a string \`pattern\``,
135	      );
136	    }
137	    if (typeof label !== "string") {
138	      throw new TypeError(
139	        `parseConfig: rule at index ${i} is missing a string \`label\``,
140	      );
141	    }
142	    if (priority !== undefined && typeof priority !== "number") {
143	      throw new TypeError(
144	        `parseConfig: rule at index ${i} has a non-numeric \`priority\``,
145	      );
146	    }
147	    return priority === undefined
148	      ? { pattern, label }
149	      : { pattern, label, priority };
150	  });
151	}
