1	#!/usr/bin/env bun
2	/**
3	 * pr-label-assigner CLI.
4	 *
5	 * Reads a path-to-label rule config and a list of changed file paths, then
6	 * prints the final label set. This is the entry point invoked by the GitHub
7	 * Actions workflow.
8	 *
9	 * Usage:
10	 *   bun run src/cli.ts --config <config.json> --files <files.txt>
11	 *   bun run src/cli.ts --config <config.json> < files.txt   (files from stdin)
12	 *
13	 * Options:
14	 *   --config <path>   JSON rule config (default: .github/labeler-config.json)
15	 *   --files  <path>   Newline-delimited changed-file list (default: stdin)
16	 *   --help            Show usage.
17	 *
18	 * Output (stdout):
19	 *   A human-readable summary, plus a machine-parseable line:
20	 *     LABELS=api,tests,documentation
21	 *   (empty label set prints `LABELS=`). Errors go to stderr with a non-zero
22	 *   exit code so CI fails loudly.
23	 */
24	import { assignLabels, parseConfig } from "./labeler.ts";
25	
26	interface CliOptions {
27	  config: string;
28	  files?: string;
29	  help: boolean;
30	}
31	
32	/** Parse argv into structured options. Throws on unknown/incomplete flags. */
33	export function parseArgs(argv: string[]): CliOptions {
34	  const opts: CliOptions = {
35	    config: ".github/labeler-config.json",
36	    help: false,
37	  };
38	  for (let i = 0; i < argv.length; i++) {
39	    const arg = argv[i];
40	    switch (arg) {
41	      case "--help":
42	      case "-h":
43	        opts.help = true;
44	        break;
45	      case "--config":
46	      case "-c":
47	        opts.config = requireValue(argv, ++i, arg);
48	        break;
49	      case "--files":
50	      case "-f":
51	        opts.files = requireValue(argv, ++i, arg);
52	        break;
53	      default:
54	        throw new Error(`Unknown argument: ${arg}`);
55	    }
56	  }
57	  return opts;
58	}
59	
60	function requireValue(argv: string[], i: number, flag: string): string {
61	  const value = argv[i];
62	  if (value === undefined) throw new Error(`Missing value for ${flag}`);
63	  return value;
64	}
65	
66	const USAGE = `pr-label-assigner — assign PR labels from changed file paths.
67	
68	Usage:
69	  bun run src/cli.ts --config <config.json> --files <files.txt>
70	  bun run src/cli.ts --config <config.json> < files.txt
71	
72	Options:
73	  -c, --config <path>  JSON rule config (default: .github/labeler-config.json)
74	  -f, --files  <path>  Newline-delimited changed-file list (default: stdin)
75	  -h, --help           Show this help.`;
76	
