2	/**
3	 * act integration harness for the PR Label Assigner workflow.
4	 *
5	 * For each test case this:
6	 *   1. Builds a temp git repo containing the project + that case's fixture
7	 *      (fixtures/changed-files.txt is overwritten with the case's file list).
8	 *   2. Runs `act push --rm` inside it, capturing all output.
9	 *   3. Appends the output to act-result.txt (clearly delimited per case).
10	 *   4. Asserts: act exit code 0, the workflow's `Job succeeded` marker is
11	 *      present, and the computed `LABELS=` line EXACTLY matches the known-good
12	 *      value for that case's input.
13	 *
14	 * Run with: bun run run-act-tests.ts
15	 * Exits non-zero if any case fails.
16	 */
17	import { spawnSync } from "node:child_process";
18	import {
19	  cpSync,
20	  mkdtempSync,
21	  rmSync,
22	  writeFileSync,
23	  appendFileSync,
24	} from "node:fs";
25	import { tmpdir } from "node:os";
26	import { join } from "node:path";
27	
28	const PROJECT_ROOT = import.meta.dir;
29	const RESULT_FILE = join(PROJECT_ROOT, "act-result.txt");
30	
31	interface ActCase {
32	  name: string;
33	  /** Newline-delimited changed-file list written into fixtures/changed-files.txt */
34	  fixture: string;
35	  /** EXACT expected value of the LABELS= line emitted by the workflow. */
36	  expectedLabels: string;
37	}
38	
39	// Known-good cases. Expected values verified against the committed config
40	// (.github/labeler-config.json) and the labeler's priority ordering.
41	const CASES: ActCase[] = [
42	  {
43	    name: "api-tests-code",
44	    fixture: "src/api/users.test.ts\nsrc/api/index.ts\n",
45	    // api(10) > tests(5) > code(0)
46	    expectedLabels: "api,tests,code",
47	  },
48	  {
49	    name: "documentation-only",
50	    fixture: "docs/intro.md\nREADME.md\n",
51	    expectedLabels: "documentation",
52	  },
53	  {
54	    name: "no-match",
55	    fixture: "Makefile\nLICENSE\n",
56	    expectedLabels: "",
57	  },
58	];
59	
60	// Files/dirs to copy into each temp repo. node_modules is intentionally
61	// excluded — the workflow needs no third-party runtime deps.
62	const COPY_ITEMS = [
63	  "src",
64	  "fixtures",
65	  ".github",
66	  "package.json",
67	  "tsconfig.json",
68	  ".actrc",
69	];
70	
71	/** Build an isolated temp git repo for one case; returns its path. */
72	function setupRepo(c: ActCase): string {
